# 1단계: SHA 가져오기
SHA=$(curl -s \
  -H "Authorization: Bearer $GITHUB_TOKEN" \
  "https://api.github.com/repos/byeol-coder/project_byeol/contents/index.html" \
  | python3 -c "import json,sys; print(json.load(sys.stdin)['sha'])")

# 2단계: 새 파일로 교체
python3 - << 'PYEOF'
import base64,json,urllib.request,os,subprocess
b64=""
token=os.environ.get("GITHUB_TOKEN","")
sha=subprocess.check_output("echo $SHA",shell=True).decode().strip()
data=json.dumps({"message":"redesign: card grid hub, no modal, direct links","content":b64,"sha":sha}).encode()
req=urllib.request.Request("https://api.github.com/repos/byeol-coder/project_byeol/contents/index.html",data=data,headers={"Authorization":f"Bearer {token}","Content-Type":"application/json"},method="PUT")
print("✅ 완료! 상태코드:",urllib.request.urlopen(req).status)
PYEOF